                var vCiWf = rule.ciWorkflow ||
                    ((RUN_JOB_PARAMS || {}).ciWorkflow) || 'quality.yml';
                var vProbe = vHead0 ? probeDispatchedState(effectiveRepoInfo, vCiWf, vHead0) : null;
